// Helper: get all unique slugs (for getStaticPaths)
export const getAllCountySlugs = () => counties.map(c => ({ params: { slug: c.slug } }));

// Helper: get county by slug
export const getCountyBySlug = (slug) => counties.find(c => c.slug === slug) || null;

// Helper: get counties by state code
export const getCountiesByState = (code) => counties.filter(c => c.code === code);
